class HopsConfigInvalid(Exception):
    pass


class OperationNotSupported(Exception):
    pass


class SSHDServiceNotExist(Exception):
    pass


class NetcatProcessNotExist(Exception):
    pass


class ExecutionError(Exception):
    def __init__(self, stdout_data, stderr_data, exit_status, **kwargs):
        super(ExecutionError, self).__init__(**kwargs)
        self._stdout_data = stdout_data
        self._stderr_data = stderr_data
        self._exit_status = exit_status

    def __repr__(self):
        return (
            "ExecutionError({data})").format(
                data=str(self))

    def __str__(self):
        return (
            "stdout_data={stdout_data!r}, "
            "stderr_data={stderr_data!r}, "
            "exit_status={exit_status!r}".format(
                stdout_data=self._stdout_data,
                stderr_data=self._stderr_data,
                exit_status=self._exit_status))


class TimeoutError(Exception):
    pass


class SshForwardingIsRequired(Exception):
    pass


class NotFoundBindIp(Exception):
    pass


class ProcessNotExisted(Exception):
    pass
